pragma solidity >=0.8.0;

contract EnvProbe {
    uint8 public mark;
    uint8 public flag;
    uint256 public numberSeen;
    uint256 public timeSeen;

    event Snapshot(uint256 number, uint256 timestamp);

    function snapshot() public {
        uint256 n = block.number;
        mark = uint8(n & 255);
        flag = uint8(block.timestamp & 1);
        numberSeen = n;
        timeSeen = block.timestamp;
        emit Snapshot(n, block.timestamp);
    }

    function getNumber() public view returns (uint256) {
        return block.number;
    }

    function getTime() public view returns (uint256) {
        return block.timestamp;
    }

    function nextNumber() public view returns (uint256) {
        return block.number + 1;
    }
}
